278 /// `DocumentFontReader.program`: a program the document's fonts name, by
279 /// its display hash: an engine font's or a document program's. Its coverage
280 /// and metrics, and with `data` the bytes a browser loads. `NotFound` for a
281 /// hash neither names.
282 pub fn program(
283     document: &pdfium::Document,
284     fonts: &FontRegistry,
285     display_hash: &str,
286     data: bool,
287 ) -> Result<(ProgramInfo, Option<Vec<u8>>), EngineError> {
288     if let Some(info) = fonts.program_info(display_hash)? {
289         let bytes = if data { fonts.program_bytes(display_hash)? } else { None };
290         return Ok((info, bytes));
291     }
292     let faces = read_document_faces(document)?;
293     let found = faces.iter().flat_map(|face| &face.programs).find(|candidate| {
294         candidate.display_sha256.as_deref() == Some(display_hash) && candidate.object_number > 0
295     });
296     let (Some(program), Some(hash)) = (found, bytes_of_hex(display_hash)) else {
297         return Err(EngineError::with_message(
298             EngineErrorCode::NotFound,
299             format!("no font program {display_hash}"),
300         ));
301     };
302     // By the hash: a stream two font dictionaries read differently is two
303     // programs.
304     let covers = document
305         .font_display_program_coverage(&hash)
306         .map_err(super::engine_error)?
307         .into_iter()
308         .map(Into::into)
309         .collect();
310     let bytes = if data {
311         Some(
312             document
313                 .font_display_program_data(&hash)
314                 .map_err(super::engine_error)?
315                 .unwrap_or_default(),
316         )
317     } else {
318         None
319     };
320     Ok((ProgramInfo { covers, ascent: program.ascent, descent: program.descent }, bytes))
321 }
