323 /// `bytesOfHex`: the 32 bytes a SHA-256's hex names. Only a display hash
324 /// the reader wrote reaches it, so anything else is `None`.
325 fn bytes_of_hex(hex: &str) -> Option<[u8; 32]> {
326     if hex.len() != 64 || !hex.is_ascii() {
327         return None;
328     }
329     let mut out = [0u8; 32];
330     for (at, byte) in out.iter_mut().enumerate() {
331         *byte = u8::from_str_radix(&hex[at * 2..at * 2 + 2], 16).ok()?;
332     }
333     Some(out)
334 }
